def extract_gui_text(data):
# Extracting only 'id' and 'text' from each element
    extracted_elements = [
        {item["id"] : item["text"]} 
        for item in data.get("elements", [])
    ]

    # Writing to a new JSON file
    output_filename = "extracted_text.json"
    with open(output_filename, "w", encoding="utf-8") as f:
        json.dump(extracted_elements, f, indent=4)

    print(f"Successfully extracted {len(extracted_elements)} elements to {output_filename}")

if __name__ == "__main__":
    # In a real scenario, you might load this from a file using json.load()
    extract_gui_text(input_data)